public class VisionClient
{
    private readonly HttpClient _httpClient;
    private readonly string _apiKey;

    public async Task<string> AnalyzeImageAsync(
        byte[] imageData,
        string prompt,
        CancellationToken ct = default)
    {
        var base64Image = Convert.ToBase64String(imageData);

        var requestBody = new
        {
            model = "gpt-4-vision-preview",
            messages = new[]
            {
                role = "user",
                content = new object[]
                {
                    type = "text",
                    text = prompt
                },
                {
                    type = "image_url",
                    image_url = new
                    {
                        url = $"data:image/jpeg;base64,{base64Image}"
                    }
                }
            }
        };

        var response = await _httpClient.PostAsJsonAsync(
            "https://api.openai.com/v1/chat/completions",
            requestBody,
            ct);

        response.EnsureSuccessStatusCode();
        var result = await response.Content.ReadFromJsonAsync<VisionResponse>(ct);
        return result.choices[0].message.content;
    }
}

// Audio transcription with Whisper
public class AudioClient
{
    public async Task<string> TranscribeAsync(
        byte[] audioData,
        CancellationToken ct = default)
    {
        using var content = new MultipartFormDataContent();
        content.Add(new ByteArrayContent(audioData), "file", "audio.mp3");
        content.Add(new StringContent("whisper-1"), "model");

        var response = await _httpClient.PostAsync(
            "https://api.openai.com/v1/audio/transcriptions",
            content,
            ct);

        response.EnsureSuccessStatusCode();
        var result = await response.Content.ReadFromJsonAsync<TranscriptionResponse>(ct);
        return result.text;
    }
}
